const FINANCIAL_EXPORT_MAX_LINES=100000;
const FINANCIAL_EXPORT_MAX_BYTES=33554432;
function financial_export_text($v):string
{
    if(!is_string($v)&&!is_int($v))throw new ReportingProblem('A report text field is unavailable.',503);$s=(string)$v;if(!preg_match('//u',$s))throw new ReportingProblem('A report text field has invalid encoding.',503);return "'".$s;
}
function financial_export_value($v,string $kind):string
{
    if($kind==='money'){if($v===null)return financial_export_text('Unavailable');if(!is_string($v))throw new ReportingProblem('A report amount is unavailable.',503);try{return accounting_decimal(accounting_cents($v));}catch(Throwable $e){throw new ReportingProblem('A report amount is invalid. No partial export was sent.',503);}}
    if($kind==='id'){if(!is_int($v)&&!is_string($v))throw new ReportingProblem('A report identifier is unavailable.',503);$s=(string)$v;if(!preg_match('/\A[1-9][0-9]*\z/',$s))throw new ReportingProblem('A report identifier is invalid.',503);return $s;}
    return financial_export_text($v??'');
}
/** fputcsv performs delimiter/quote/newline escaping. Add enclosures to simple fields too. */
function financial_export_cell(string $s):string
{
    // Only the single-cell quoting buffer is in memory. The validated complete-file
    // spool below remains disk-backed and must finish before a successful response.
    static $encoder=null;if($encoder===null){$encoder=fopen('php://memory','w+b');if($encoder===false)throw new ReportingProblem('Export temporary storage is unavailable. Try again later.',503);}rewind($encoder);if(!ftruncate($encoder,0)||fputcsv($encoder,[$s],',','"','',"\r\n")===false)throw new ReportingProblem('The export could not be completed.',503);rewind($encoder);$encoded=stream_get_contents($encoder);if($encoded===false)throw new ReportingProblem('The export could not be completed.',503);$encoded=substr($encoded,0,-2);return str_starts_with($encoded,'"')?$encoded:'"'.$encoded.'"';
}
function financial_export_section(string $title,array $rows,array $columns,?array $totals=null):array{return compact('title','rows','columns','totals');}
function financial_export_component(string $name,array $data):array
{
    $account=['account_name','Account','text'];$sections=[];$totals=[];
    if($name==='worksheet'){
        $cols=[$account];foreach(['opening_debit','opening_credit','CRB_debit','CRB_credit','CDB_debit','CDB_credit','GJ_debit','GJ_credit','ending_debit','ending_credit','statement_debit','statement_credit','position_debit','position_credit','excluded_or_prior_result_bridge'] as $k)$cols[]=[$k,(['statement_debit'=>'Monthly result debit','statement_credit'=>'Monthly result credit','excluded_or_prior_result_bridge'=>'Prior / excluded result'][$k]??ucwords(str_replace('_',' ',$k))).' (PHP)','money'];$rows=$data['rows'];$rows[]=array_merge(['account_name'=>'Independently derived results'],array_fill_keys(array_column($cols,0),'0.00'),$data['derived_results'],['account_name'=>'Independently derived results']);$sections[]=financial_export_section('Monthly worksheet',$rows,$cols,$data['totals']);
    }elseif($name==='trial_balance'){$sections[]=financial_export_section('Trial Balance',$data['rows'],[$account,['ending_debit','Debit (PHP)','money'],['ending_credit','Credit (PHP)','money']],['ending_debit'=>$data['total_debits'],'ending_credit'=>$data['total_credits']]);$totals=['Difference'=>$data['difference']];}
    elseif($name==='income_statement'||$name==='financial_position'){$sections[]=financial_export_section(REPORT_COMPONENT_TITLES[$name],$data['rows'],[['section','Section','text'],$account,['amount','Amount (PHP)','money']]);$keys=$name==='income_statement'?['income','expenses','surplus_deficit']:['assets','liabilities','posted_equity','unclosed_accumulated_result','difference'];foreach($keys as $k)$totals[ucwords(str_replace('_',' ',$k))]=$data[$k];}
    elseif($name==='cash_flows'){
        foreach(['opening_cash','result','noncash_adjustments','working_capital','reclassifications','operating','investing','financing','net_cash_flow','closing_cash','difference'] as $k)$totals[ucwords(str_replace('_',' ',$k))]=$data[$k];
        $sections[]=financial_export_section('Noncash disclosures; excluded from physical cash',$data['noncash_disclosures'],[['journal_id','Journal','id'],['label','Description','text'],['amount','Amount (PHP)','money']]);$sections[]=financial_export_section('Cash transaction bridge',$data['transaction_bridge'],[['journal_id','Journal','id'],['cash_change','Cash change','money'],['operating','Operating','money'],['investing','Investing','money'],['financing','Financing','money']]);
    }elseif($name==='project_activity')$sections[]=financial_export_section('Project activity; line tags, not independently balanced ledgers',$data,[['project_name','Project / operations','text'],$account,['debit','Debit (PHP)','money'],['credit','Credit (PHP)','money'],['recognized_expense','Recognized expense (PHP)','money']]);
    elseif($name==='advance_aging')$sections[]=financial_export_section('Advance aging at cutoff',$data,[['number','Advance','text'],['employee','Accountable employee','text'],['due_date','Deadline','text'],['settlement_status','State','text'],['released','Released (PHP)','money'],['liquidated','Liquidated (PHP)','money'],['returned','Returned (PHP)','money'],['outstanding','Outstanding (PHP)','money'],['aging_bucket','Aging','text']]);
    elseif($name==='budget_actuals'){$sections[]=financial_export_section($data['approved']?'Effective approved revision '.$data['approved']['revision']:'No approved budget; amounts unavailable',$data['rows'],[['account_label','Expense account','text'],['project_label','Project / operations','text'],['approved_amount','Approved (PHP)','money'],['actual','Actual (PHP)','money'],['remaining','Remaining (PHP)','money']],['approved_amount'=>$data['approved_total'],'actual'=>$data['actual_total'],'remaining'=>$data['remaining_total']]);}
    else throw new ReportingProblem('Choose a supported report.',400);
    if($totals){$rows=[];foreach($totals as $label=>$value)$rows[]=['label'=>$label,'amount'=>$value];$sections[]=financial_export_section('Report totals',$rows,[['label','Total','text'],['amount','Amount (PHP)','money']]);}return $sections;
}
function financial_export_record_label($v):string{return trim((string)($v??''))===''?'Not recorded':trim((string)$v);}
function financial_export_record_money(string $v):string{return accounting_money($v);}
/** Explicit new presentation choices. Existing detailed export URLs retain their contract. */
function financial_export_transactions(PDO $pdo,int $uid,array $request,string $kind,string $representation):array
{
    if($kind!=='history'&&!stage1_enabled($pdo))throw new ReportingProblem('Enable the accounting workspace setup before exporting a complete cash book.',503);
    $request['view']=$kind==='history'?'records':$kind;$data=transaction_records_model($pdo,$uid,$request,true);
    $title=['history'=>'Transaction History','cdb'=>'Cash Disbursements Book','crb'=>'Cash Receipts Book'][$kind];$rows=[];
    if($representation==='transactions'){
        foreach($data['rows'] as $row){$row['summary']=$row['amount']===null?$row['amount_text']:'';$rows[]=$row;}
        $columns=[['journal_id','Journal','id'],['date_label','Date','text'],['type','Type','text'],['reference','Reference','text'],['party','Party','text'],['purpose','Purpose','text'],['project','Project','text'],['amount','Amount (PHP)','money'],['summary','Summary','text']];
    }else{
        foreach($data['rows'] as $row)foreach($data['journals'][$row['journal_id']]['lines'] as $line)$rows[]=$line+['party'=>$row['party'],'purpose'=>$row['purpose'],'account'=>($line['account_code']?:'#'.$line['account_id']).' · '.$line['account_name'].' · '.$line['account_type'],'project'=>transaction_project_label($line)];
        $columns=[['journal_id','Journal','id'],['entry_date','Date','text'],['reference','Reference','text'],['party','Party','text'],['purpose','Purpose','text'],['account','Account','text'],['project','Project','text'],['debit_amount','Debit (PHP)','money'],['credit_amount','Credit (PHP)','money']];
    }
    $accountLabel='All accounts';foreach($data['accounts'] as $a)if((string)$a['CategoryID']===$data['criteria']['account_id'])$accountLabel=$a['Name'];
    $projectLabel=$data['criteria']['project_id']==='0'?'Organization operations':'All projects';foreach($data['projects'] as $p)if((string)$p['id']===$data['criteria']['project_id'])$projectLabel=$p['name'];
    return ['title'=>$title,'generated_at'=>$data['generated_at'],'metadata'=>['Period'=>($data['criteria']['from']?transaction_date($data['criteria']['from']):'Any date').' to '.($data['criteria']['to']?transaction_date($data['criteria']['to']):'Any date'),'Matching transactions'=>$data['matching_count'],'Search'=>$data['criteria']['search']?:'None','Transaction type'=>[''=>'All types','CDB'=>'Payments','CRB'=>'Money Received','GJ'=>'General Journal / Reversals'][$data['criteria']['book']],'Account'=>$accountLabel,'Account type'=>$data['criteria']['type']?:'All account types','Project'=>$projectLabel,'Scope'=>$representation==='transactions'?'Complete matching transaction list':'Every line of each matching transaction'],
        'sections'=>[financial_export_section($representation==='transactions'?$title:'Detailed journal lines',$rows,$columns)]];
}
function financial_export_records(PDO $pdo,array $request,string $kind):array
{
    if($kind!=='history'&&!stage1_enabled($pdo))throw new ReportingProblem('Full-entry cash-book export needs the saved accounting workspace setup. Journal History can export the validated posted lines.',503);
    $get=$request;$get['view']='records';$get['format']='html';$r=accounting_records_request($get,accounting_accounts($pdo),accounting_today());if($r['errors'])throw new ReportingProblem(implode(' ',array_values($r['errors'])),400);$r['filters']['context']=$kind==='history'?'records':$kind;$data=accounting_records($pdo,$r['filters']);$terms=preg_split('/\s+/u',mb_strtolower(trim($r['state']['search']),'UTF-8'),-1,PREG_SPLIT_NO_EMPTY);$rows=$data['rows'];
    $account=static fn($row)=>($row['account_code']?:'#'.$row['account_id']).' · '.$row['account_name'].' · '.$row['account_type'];$has=static function(string $hay)use($terms):bool{$hay=mb_strtolower($hay,'UTF-8');foreach($terms as $term)if(!str_contains($hay,$term))return false;return true;};
    if($terms&&$data['completeBook']){$ids=[];foreach($data['journals'] as $id=>$j){$h=$j['header'];$party=$h['party_snapshot']?json_decode($h['party_snapshot'],true,32,JSON_THROW_ON_ERROR):[];$hay=[$h['entry_date'],$h['reference'],$h['description'],$party['name']??'',$j['evidence_coverage']['status']??''];foreach($j['corrections'] as $c)array_push($hay,'Correction #'.$c['id'],$c['role'],$c['accounting_date'],$c['reason']);foreach($j['lines'] as $line)array_push($hay,$account($line),$line['project_code_snapshot'],$line['project_name_snapshot'],financial_export_record_money($line['debit_amount']),financial_export_record_money($line['credit_amount']));if($has(implode(' ',$hay)))$ids[(int)$id]=true;}$rows=array_values(array_filter($rows,fn($row)=>isset($ids[(int)$row['journal_id']])));}
    elseif($terms)$rows=array_values(array_filter($rows,fn($row)=>financial_search_history($r['state']['search'],[financial_export_record_label($row['entry_date']),financial_export_record_label($row['reference']),financial_export_record_label($row['description']).' '.($row['correction_search']??''),$account($row),financial_export_record_money($row['debit_amount']),financial_export_record_money($row['credit_amount'])])));
    $keys=['entry_date','reference','description','account','debit_amount','credit_amount'];$order=$r['state']['order']?:[[0,'desc']];usort($rows,static function($a,$b)use($keys,$order,$account){foreach($order as [$col,$direction]){$key=$keys[$col];if($col>=4)$cmp=accounting_cents($a[$key])<=>accounting_cents($b[$key]);else{$left=$key==='account'?$account($a):financial_export_record_label($a[$key]);$right=$key==='account'?$account($b):financial_export_record_label($b[$key]);$cmp=financial_search_compare($left,$right);}if($cmp)return $direction==='asc'?$cmp:-$cmp;}return ((int)$b['journal_id']<=>(int)$a['journal_id'])?:((int)$a['line_id']<=>(int)$b['line_id']);});$debit=$credit=0;foreach($rows as &$row){$row['account']=$account($row);$debit=accounting_add($debit,accounting_cents($row['debit_amount']));$credit=accounting_add($credit,accounting_cents($row['credit_amount']));}unset($row);
    return ['metadata'=>['Scope'=>$data['completeBook']?'All matching complete originating entries; gross activity includes corrected originals':'All matching posted journal lines; line filters apply','From'=>$r['filters']['from']?:'Unbounded','To'=>$r['filters']['to']?:'Unbounded','Literal search'=>$r['state']['search'],'Sort'=>$request['sort']??'0:desc','Matching lines'=>count($rows)],'sections'=>[financial_export_section($kind==='history'?'Journal History':strtoupper($kind).' gross originating activity',$rows,[['journal_id','Journal','id'],['entry_date','Date','text'],['reference','Reference','text'],['description','Description','text'],['account','Account','text'],['debit_amount','Debit (PHP)','money'],['credit_amount','Credit (PHP)','money']],['debit_amount'=>accounting_decimal($debit),'credit_amount'=>accounting_decimal($credit)])]];
}
function financial_export_model(PDO $pdo,int $uid,array $r):array
{
    return accounting_read($pdo,function()use($pdo,$uid,$r){reporting_actor($pdo,$uid);$kind=reporting_text($r['kind']??'',30,'export type',true);$rowCount=(int)$pdo->query("SELECT COUNT(*) FROM journal_entry_lines l JOIN journal_entries j ON j.id=l.journal_entry_id WHERE j.status='posted'")->fetchColumn();if($rowCount>FINANCIAL_EXPORT_MAX_LINES&&!in_array($kind,['frozen','snapshot'],true))throw new ReportingProblem('This installation can export up to 100,000 source lines at once. Ask the administrator to arrange a larger validated export. No partial file was sent.',413);
        $meta=['Organization'=>'Atikha Finance','Currency'=>'PHP','Text protection'=>'Text cells begin with an apostrophe for spreadsheet viewing; remove only deliberately. No external-system compatibility is claimed.'];$sections=[];$title='';
        if($kind==='ledger'){$data=ledger_read($pdo,$uid,$r,false,true);if(!$data['account'])throw new ReportingProblem('Choose an account before exporting.',400);$title='General Ledger';$meta+=['Account'=>$data['account']['Name'],'From'=>$data['criteria']['from'],'To'=>$data['criteria']['to'],'Scope'=>'All matching rows; running balances include movements hidden by search','Literal search'=>$data['criteria']['search'],'Opening balance'=>$data['opening'],'Full-period debit'=>$data['period_debits'],'Full-period credit'=>$data['period_credits'],'Ending balance'=>$data['ending'],'Matching rows'=>$data['matching_count']];$sections[]=financial_export_section('Chronological account movements',$data['rows'],[['entry_date','Date','text'],['journal_id','Journal','id'],['reference','Reference','text'],['description','Description','text'],['party_name','Party','text'],['project_name_snapshot','Project / operations','text'],['debit_amount','Debit (PHP)','money'],['credit_amount','Credit (PHP)','money'],['running_balance','Running balance (debit positive, credit negative)','money']]);}
        elseif(in_array($kind,['history','crb','cdb'],true)){
            $representation=reporting_text($r['representation']??'',30,'export presentation');
            if($representation!==''){
                if(!in_array($representation,['transactions','transaction_lines'],true))throw new ReportingProblem('Choose a listed export presentation.',400);
                $m=financial_export_transactions($pdo,$uid,$r,$kind,$representation);$meta+=$m['metadata'];$sections=$m['sections'];$title=$m['title'];
            }else{$m=financial_export_records($pdo,$r,$kind);$meta+=$m['metadata'];$sections=$m['sections'];$title=$kind==='history'?'Journal History':strtoupper($kind).' gross originating activity';}
        }
        elseif($kind==='snapshot'){$tb=report_snapshot_load_id($pdo,reporting_id($r['snapshot_id']??null,'saved Trial Balance'));if(!$tb)throw new ReportingProblem('Saved Trial Balance not found.',404);if($tb['invalid_journals']||$tb['difference']!=='0.00')throw new ReportingProblem('This saved Trial Balance needs an integrity review.',503);$title='Submitted Trial Balance';$meta+=['Scope'=>'Exact saved Trial Balance copy','Frozen revision'=>$tb['header']['revision'],'As of'=>$tb['as_of'],'Prepared by'=>$tb['header']['submitter_name'],'State'=>$tb['header']['review_status']];$rows=[];foreach($tb['rows'] as $row)$rows[]=['account_name'=>$row['Name'],'ending_debit'=>$row['debit_balance'],'ending_credit'=>$row['credit_balance']];$sections=financial_export_component('trial_balance',['rows'=>$rows,'total_debits'=>$tb['total_debits'],'total_credits'=>$tb['total_credits'],'difference'=>$tb['difference']]);}
        elseif(in_array($kind,['live','frozen'],true)){$component=reporting_text($r['component']??'',40,'report',true);if(!isset(REPORT_COMPONENT_TITLES[$component]))throw new ReportingProblem('Choose a valid report.',400);$title=REPORT_COMPONENT_TITLES[$component];if($kind==='frozen'){$bundle=report_bundle_load($pdo,$uid,reporting_id($r['bundle_id']??null),false);$data=$bundle['payload']['components'][$component];$meta+=['Month'=>$bundle['month'],'Scope'=>'Exact stored frozen component','Frozen revision'=>$bundle['revision'],'State'=>$bundle['state'],'Prepared by'=>$bundle['prepared_by'],'Prepared at'=>$bundle['prepared_at']];}
            else{$month=reporting_month($r['month']??substr(accounting_today(),0,7));$m=report_bundle_model($pdo,$uid,$month);$data=$m['components'][$component];$meta+=['Month'=>$month,'From'=>$m['from'],'Actuals through'=>$m['as_of'],'Scope'=>'Live report; changes with later authorized postings/configuration','Completeness'=>$m['complete']?'Complete':'Incomplete: '.implode(' ',$m['issues'])];if(!$m['complete']&&!in_array($component,['worksheet','trial_balance','project_activity','advance_aging','budget_actuals'],true))throw new ReportingProblem('Complete the report setup and resolve the listed issues before exporting this statement.',422);}if($kind==='frozen')$meta+=['From'=>$bundle['payload']['manifest']['from'],'Actuals through'=>$bundle['payload']['manifest']['as_of']];$sections=financial_export_component($component,$data);}
        else throw new ReportingProblem('Choose a supported export.',400);return ['kind'=>$kind,'title'=>$title,'metadata'=>$meta,'sections'=>$sections,'transaction_presentation'=>in_array($kind,['history','crb','cdb'],true)&&!empty($r['representation']),'generated_at'=>isset($representation)&&$representation!==''?$m['generated_at']:(new DateTimeImmutable('now',new DateTimeZone('Asia/Manila')))->format('Y-m-d H:i:s').' Asia/Manila','filename'=>'atikha-'.$kind.'-'.date('Ymd-His').'.csv'];
    });
}
/** No successful response is sent until every model cell has been validated and spooled. */
function financial_export_spool(array $model)
{
    $spool=tmpfile();if($spool===false)throw new ReportingProblem('Export temporary storage is unavailable. Try again later.',503);$rows=0;
    try{$write=static function(array $values)use($spool,&$rows){if(++$rows>FINANCIAL_EXPORT_MAX_LINES+1000)throw new ReportingProblem('The export is too large. No partial file was sent.',413);$line=implode(',',array_map('financial_export_cell',$values))."\r\n";if(fwrite($spool,$line)!==strlen($line)||ftell($spool)>FINANCIAL_EXPORT_MAX_BYTES)throw new ReportingProblem('The export exceeded available storage or the 32 MiB limit. No partial file was sent.',413);};$write([financial_export_text($model['title'])]);foreach($model['metadata'] as $key=>$value)$write([financial_export_text($key),in_array($key,['Opening balance','Full-period debit','Full-period credit','Ending balance'],true)?financial_export_value($value,'money'):financial_export_text(is_int($value)?(string)$value:$value)]);$write([financial_export_text('Generated'),financial_export_text($model['generated_at'])]);$write([]);
        foreach($model['sections'] as $section){$write([financial_export_text($section['title'])]);$write(array_map(fn($col)=>financial_export_text($col[1]),$section['columns']));foreach($section['rows'] as $row)$write(array_map(fn($col)=>financial_export_value($row[$col[0]]??null,$col[2]),$section['columns']));if($section['totals']!==null){$values=[];foreach($section['columns'] as $n=>$col)$values[]=$n===0?financial_export_text('Total'):(isset($section['totals'][$col[0]])?financial_export_value($section['totals'][$col[0]],$col[2]):financial_export_text(''));$write($values);}$write([]);}rewind($spool);return $spool;
    }catch(Throwable $e){fclose($spool);throw $e;}
}
